import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';
import '../models/records.dart';
class SettingsScreen extends StatelessWidget{
 const SettingsScreen({super.key,required this.role,required this.themeMode,required this.onRole,required this.onTheme,required this.count,required this.onExport});
 final UserRole role;final AppThemeMode themeMode;final ValueChanged<UserRole>onRole;final ValueChanged<AppThemeMode>onTheme;final int count;final VoidCallback onExport;
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(18),children:[
  Text('Control centre',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),
  Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ACTIVE ROLE',style:TextStyle(fontSize:10,color:Colors.grey,letterSpacing:1.3)),const SizedBox(height:10),SegmentedButton<UserRole>(segments:const [ButtonSegment(value:UserRole.manager,label:Text('Manager'),icon:Icon(Icons.admin_panel_settings)),ButtonSegment(value:UserRole.crew,label:Text('Crew / Clerk'),icon:Icon(Icons.local_shipping))],selected:{role},onSelectionChanged:(s)=>onRole(s.first)),const SizedBox(height:8),Text(role==UserRole.manager?'Full tariff, override and record management access.':'Field access: pickups, payment capture and weigh-ins. Admin controls are restricted.',style:const TextStyle(color:Colors.grey))]))),
  const SizedBox(height:10),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('DISPLAY THEME',style:TextStyle(fontSize:10,color:Colors.grey,letterSpacing:1.3)),RadioListTile<AppThemeMode>(contentPadding:EdgeInsets.zero,value:AppThemeMode.eco,groupValue:themeMode,title:const Text('Eco Obsidian'),subtitle:const Text('Forest dark · emerald accents'),onChanged:(v)=>onTheme(v!)),RadioListTile<AppThemeMode>(contentPadding:EdgeInsets.zero,value:AppThemeMode.daylight,groupValue:themeMode,title:const Text('Daylight Clean'),subtitle:const Text('Bright, crisp surfaces'),onChanged:(v)=>onTheme(v!)),RadioListTile<AppThemeMode>(contentPadding:EdgeInsets.zero,value:AppThemeMode.truck,groupValue:themeMode,title:const Text('High-Contrast Truck'),subtitle:const Text('Amber and white for outdoor use'),onChanged:(v)=>onTheme(v!))]))),
  Card(child:ListTile(leading:const Icon(Icons.storage),title:const Text('Offline local storage'),subtitle:Text('$count subscribers · saved on this device'),trailing:const Chip(label:Text('READY')))),
  Card(child:ListTile(leading:const Icon(Icons.file_download_outlined),title:const Text('Export operations summary'),subtitle:const Text('Download CSV ledger for backup and reporting'),onTap:onExport,trailing:const Icon(Icons.chevron_right))),
  Card(child:ListTile(leading:const Icon(Icons.android),title:const Text('Android APK centre'),subtitle:const Text('Download the latest signed release APK'),trailing:const Icon(Icons.download),onTap:()=>_download(context))),
  const Padding(padding:EdgeInsets.all(12),child:Text('TakaTrack · Offline-first field operations · KES currency',textAlign:TextAlign.center,style:TextStyle(color:Colors.grey,fontSize:11))),
 ]);
 Future<void> _download(BuildContext c) async {final uri=Uri.parse('https://github.com/kennedy-blip/Taka-track/releases/latest/download/app-release.apk');final ok=await launchUrl(uri,mode:LaunchMode.externalApplication);if(!ok&&c.mounted){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Could not open the APK download. Visit the GitHub Releases page.')));}}
}
